import {escapeHTML as e,safeURL,queryFor,normalize,shortlist,comparison,reportHTML,validBounds,normalizeCatalog,MONEY,estimateCost,distanceKm,greenFeeText,extraFeeText} from './core.js';
const $=id=>document.getElementById(id),params=new URLSearchParams(location.search);
let map,layer,snapshot=null,controller=null,sequence=0,movingTimer,cooldownUntil=0,catalog=[],catalogData=null;
const compareIds=new Set(),compareSnapshots=new Map(),savedSnapshots=new Map();
try{for(const c of JSON.parse(localStorage.getItem('fri-atlas-saved-courses')||'[]')){if(c&&typeof c.id==='string'&&typeof c.name==='string'&&c.tags)savedSnapshots.set(c.id,c);}}catch{}
let favorites=new Set();try{favorites=new Set(JSON.parse(localStorage.getItem('fri-atlas-favorites')||'[]'));}catch{}
const allCourses=()=>[...(snapshot?.items||[]),...catalog,...savedSnapshots.values()];
const findCourse=id=>compareSnapshots.get(id)||allCourses().find(c=>c.id===id);

const number=(key,fallback,min,max)=>{const raw=params.get(key),v=raw===null?fallback:Number(raw);return Number.isFinite(v)&&v>=min&&v<=max?v:fallback;};
const currentBounds=()=>{const b=map.getBounds();return {s:b.getSouth(),w:b.getWest(),n:b.getNorth(),e:b.getEast()};};
const matches=(a,b)=>a&&b&&['s','w','n','e'].every(k=>Math.abs(a[k]-b[k])<.00001);
const limit=()=>Number($('limitSelect').value);
const selected=()=>snapshot?shortlist($('favoriteOnly').checked?snapshot.items.filter(c=>favorites.has(c.id)):snapshot.items,$('searchInput').value,$('sortSelect').value,limit()):[];
function status(message,error=false){$('status').textContent=message;$('status').classList.toggle('error',error);}
function updateNavigator(){if(!map)return;const b=currentBounds();$('zoomText').textContent=`ZOOM ${map.getZoom()}`;$('boundsText').textContent=`현재 영역 S ${b.s.toFixed(3)} / W ${b.w.toFixed(3)} / N ${b.n.toFixed(3)} / E ${b.e.toFixed(3)}`;if(snapshot){const same=matches(snapshot.bounds,b),oldObserved=snapshot.items.filter(c=>c.lat>=b.s&&c.lat<=b.n&&c.lon>=b.w&&c.lon<=b.e).length;$('visibleCount').textContent=same?snapshot.items.length:'미조회';$('snapshotCount').textContent=snapshot.items.length;$('navDetail').textContent=same?'현재 화면: 분석 완료 · 관측한 등록 후보 수입니다.':'현재 화면: 미조회 · 분석 필요. 이전 스냅샷에서 이 화면에 남은 관측 후보 '+oldObserved+'곳.';const q=snapshot.bounds,missing=snapshot.items.filter(c=>!c.official?.green_fees?.length||!c.official?.rating||c.official?.booking?.status!=='verified').length;$('lastAnalysis').textContent=`마지막 분석: ${snapshot.time}\n분석 영역 S ${q.s.toFixed(3)} / W ${q.w.toFixed(3)} / N ${q.n.toFixed(3)} / E ${q.e.toFixed(3)}\n원천 객체 ${snapshot.rawCount??'미제공'} · 대표점 필터/동일ID 제거후 ${snapshot.items.length} · 표시 ${selected().length} · 미표시 ${Math.max(0,snapshot.items.length-selected().length)}\n요금·평가·예약 중 미확인 코스 ${missing} · 실제 운영코스의 의미상 중복 수 미제공`;}else{$('visibleCount').textContent='미조회';$('navDetail').textContent='현재 화면 좌표만 갱신 중입니다. 자동 검색 요청은 보내지 않습니다.';$('lastAnalysis').textContent='마지막 분석: 없음 · 원천/필터후/결측 수 미제공';}}
function courseCard(c,i){const web=safeURL(c.tags.website||c.tags['contact:website']),o=c.official;const prices=o?.green_fees||[];const fee=prices.length?`평일 ${MONEY(Math.min(...prices.map(f=>f.weekday)))}부터*`:'미확인';return `<article class="course-card"><div class="card-top"><span class="course-number">${String(i+1).padStart(2,'0')}</span><div class="course-title"><h3>${e(c.name)}</h3><span>${o?'공식자료 대조 · 위치는 별도 출처':'OSM 등록명'} · 목록 번호 / 추천 순위 아님</span></div><span class="course-chip">INFO ${c.evidence}/8</span></div><div class="course-summary"><div><span>GREEN FEE</span><b>${e(fee)}</b></div><div><span>HOLES / PAR</span><b>${e(c.tags['golf:holes']||'—')} / ${e(c.tags['golf:par']||'—')}</b></div><div><span>CENTER DISTANCE</span><b>${Number.isFinite(c.distance)?c.distance.toFixed(1)+' km':Number.isFinite(c.lat)?'화면 분석 전':'좌표 미확인'}</b></div></div><p class="course-comment">${prices.length?'*공식 일반요금 참고값 · 조건별 상이 · 선택일 실시간 견적 아님.':'요금·운영·평가·예약은 별도 확인이 필요합니다.'}<br>전경 사진 미확보 · 거리는 화면 중심 직선거리입니다.</p><div class="course-links">${o?`<a href="${e(safeURL(o.name.source_url)||'#')}" target="_blank" rel="noopener noreferrer">공식자료 출처 ↗</a>`:`<a href="https://www.openstreetmap.org/${e(c.id)}" target="_blank" rel="noopener noreferrer">지도 원본 ↗</a>`}${web?`<a href="${e(web)}" target="_blank" rel="noopener noreferrer">${o?'공식 홈페이지':'등록 웹사이트 (공식성 미검증)'} ↗</a>`:''}${o?.fee_guide?.value&&safeURL(o.fee_guide.value)?`<a href="${e(safeURL(o.fee_guide.value))}" target="_blank" rel="noopener noreferrer">요금 안내 ↗</a>`:''}${o?.booking?.status==='verified'&&safeURL(o.booking.url)?`<a href="${e(safeURL(o.booking.url))}" target="_blank" rel="noopener noreferrer">공식 예약 ↗</a>`:'<span>직접 예약 URL 미확인 · 홈페이지 메뉴 이용</span>'}<a href="https://www.google.com/search?q=${encodeURIComponent(c.name+' 이용 후기')}" target="_blank" rel="noopener noreferrer">리뷰 검색 ↗ (평가 미수집)</a></div><div class="card-buttons"><button class="secondary ${compareIds.has(c.id)?'active':''}" data-compare="${e(c.id)}">${compareIds.has(c.id)?'비교에서 빼기':'비교에 담기'}</button><button class="secondary ${favorites.has(c.id)?'active':''}" data-favorite="${e(c.id)}">${favorites.has(c.id)?'♥ 관심 저장됨':'♡ 관심 저장'}</button></div><details><summary>전체 ${comparison(c).length}개 비교 항목 펼치기</summary><dl class="comparison">${comparison(c).map(([k,v])=>`<dt>${e(k)}</dt><dd>${e(v)}</dd>`).join('')}</dl></details></article>`;}
function render(){if(!snapshot)return;document.querySelector('.map-source').innerHTML=snapshot.provider==='catalog'?'지도 © OpenStreetMap contributors · 후보: 공식자료 초기 카탈로그<br>대표점 출처는 각 코스 비교 항목에 별도 표시 · 전체 골프장 수 아님':'지도 © OpenStreetMap contributors · 검색 Overpass API (제한적 실험)<br>대표점 기준 · 공개지도 수록 범위만 검색 · 전체 골프장 수 아님';const items=selected();$('displayCount').textContent=items.length;$('displayCount').nextElementSibling.textContent=`표시 중 / 최대 ${limit()}`;layer?.clearLayers();$('results').innerHTML=items.length?items.map(courseCard).join(''):'<div class="empty-state"><h3>표시할 후보가 없습니다.</h3><p>다른 지역을 분석하거나 실험 조회를 선택해 보세요.<br>초기 카탈로그 미등재는 골프장 부재를 뜻하지 않습니다.</p></div>';items.forEach((c,i)=>{if(!Number.isFinite(c.lat)||!Number.isFinite(c.lon))return;const marker=L.marker([c.lat,c.lon],{icon:L.divIcon({className:'marker-pin',html:String(i+1),iconSize:[27,27]})});const label=document.createElement('span');label.textContent=c.name;marker.bindPopup(label).addTo(layer);});$('downloadButton').disabled=false;$('mailButton').disabled=false;updateNavigator();renderTray();}
function renderSaved(){const courses=[...savedSnapshots.values()].filter(c=>favorites.has(c.id));$('savedResults').innerHTML=courses.length?courses.map(courseCard).join(''):'저장한 관심 골프장이 없습니다. 코스의 ♡ 관심 저장을 눌러 보세요.';}
function renderCatalog(){ $('catalogResults').innerHTML=catalog.length?catalog.filter(c=>!$('favoriteOnly').checked||favorites.has(c.id)).map(courseCard).join(''):'초기 카탈로그 자료를 불러오지 못했습니다.';}
function renderTray(){const courses=[...compareIds].map(findCourse).filter(Boolean);if(!courses.length){$('compareTray').textContent='각 코스의 비교에 담기를 눌러 최대 4곳을 비교하세요.';return;}const rows=[['구분',c=>c.official?'공식 공개자료':'OSM 후보'],['홀 수',c=>c.tags['golf:holes']||'미확인'],['주중 요금',c=>c.official?.green_fees?.map(f=>greenFeeText(f,'weekday')).join(' / ')||'미확인'],['주말 요금',c=>c.official?.green_fees?.map(f=>greenFeeText(f,'weekend')).join(' / ')||'미확인'],['카트비',c=>extraFeeText(c.official?.cart_fee)],['캐디피',c=>extraFeeText(c.official?.caddie_fee)],['선택일 1인 총액',c=>estimateCost(c,$('playDate').value,Number($('partySize').value)).text],['후기·품질평가',c=>'미수집 · 순위 미산정'],['가격 확인',c=>c.official?.name?.checked_at||'미확인']];$('compareTray').innerHTML=`<p class="catalog-note">${courses.length}/4곳 · 요금은 공식 일반안내 참고값입니다. 날짜만으로 공휴일·시즌·티타임 요금을 추정하지 않습니다.</p><div class="compare-scroll"><table><thead><tr><th>비교 항목</th>${courses.map(c=>`<th>${e(c.name)}<br><button class="text-button" data-compare="${e(c.id)}">빼기 ×</button></th>`).join('')}</tr></thead><tbody>${rows.map(([label,get])=>`<tr><th>${e(label)}</th>${courses.map(c=>`<td>${e(get(c))}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
document.addEventListener('click',event=>{const b=event.target.closest('button[data-compare],button[data-favorite]');if(!b)return;if(b.dataset.compare){const id=b.dataset.compare;if(compareIds.has(id)){compareIds.delete(id);compareSnapshots.delete(id);}else if(compareIds.size<4){const c=findCourse(id);if(c){compareIds.add(id);compareSnapshots.set(id,structuredClone(c));}}else{status('비교는 최대 4곳입니다. 한 곳을 뺀 뒤 추가해 주세요.',true);return;}}else{const id=b.dataset.favorite;if(favorites.has(id)){favorites.delete(id);savedSnapshots.delete(id);}else{const c=findCourse(id);if(c){favorites.add(id);savedSnapshots.set(id,structuredClone(c));}}try{localStorage.setItem('fri-atlas-favorites',JSON.stringify([...favorites]));localStorage.setItem('fri-atlas-saved-courses',JSON.stringify([...savedSnapshots.values()]));status('관심 골프장을 이 브라우저에 저장했습니다.');}catch{status('브라우저 저장을 사용할 수 없습니다. 이번 화면에서만 유지합니다.',true);}}render();renderCatalog();renderSaved();renderTray();});
$('clearCompare').addEventListener('click',()=>{compareIds.clear();compareSnapshots.clear();render();renderCatalog();renderSaved();renderTray();});
$('favoriteOnly').addEventListener('change',()=>{render();renderCatalog();});
for(const id of ['playDate','partySize'])$(id).addEventListener('change',renderTray);
function cancel(){sequence++;controller?.abort();controller=null;$('cancelButton').hidden=true;$('analyzeButton').disabled=false;if(map){map.dragging.enable();map.scrollWheelZoom.enable();map.doubleClickZoom.enable();map.touchZoom.enable();map.keyboard.enable();map.boxZoom.enable();if(map.zoomControl){map.zoomControl.enable?.();}}status('분석을 취소했습니다. 이전 결과를 유지합니다.');}
function lockMap(locked){for(const k of ['dragging','scrollWheelZoom','doubleClickZoom','touchZoom','keyboard','boxZoom'])map[k][locked?'disable':'enable']();document.querySelectorAll('.leaflet-control-zoom a').forEach(x=>{x.style.pointerEvents=locked?'none':'';x.setAttribute('aria-disabled',String(locked));});$('koreaButton').disabled=locked;}
async function analyze(){if(!map)return;if(controller)cancel();const b=currentBounds();if($('providerSelect').value==='catalog'){if(!validBounds(b)){status('날짜변경선·세계 반복 영역은 지원하지 않습니다. 지도를 이동해 주세요.',true);return;}const items=catalog.filter(c=>Number.isFinite(c.lat)&&Number.isFinite(c.lon)&&c.lat>=b.s&&c.lat<=b.n&&c.lon>=b.w&&c.lon<=b.e).map(c=>({...c,distance:distanceKm({lat:(b.s+b.n)/2,lon:(b.w+b.e)/2},c)}));snapshot={bounds:{...b},time:new Date().toLocaleString('ko-KR',{timeZone:'Asia/Seoul'})+' KST',dataTime:catalogData?.checked_at,provider:'catalog',rawCount:catalog.length,items};render();status(`초기 카탈로그 ${catalog.length}곳 중 화면 내 ${items.length}곳 · 전체 골프장 수가 아닙니다 · 순위 미산정`);return;}let query;try{query=queryFor(b);}catch(error){status(error.message,true);return;}if(Date.now()<cooldownUntil){status('공유 API 보호를 위해 잠시 후 다시 분석해 주세요. 요청 간격은 15초입니다.',true);return;}const id=++sequence;controller=new AbortController();const aborter=controller;let timedOut=false;const timer=setTimeout(()=>{timedOut=true;aborter.abort();},45000);$('analyzeButton').disabled=true;$('cancelButton').hidden=false;lockMap(true);status('선택한 화면을 고정했습니다. 공개지도에서 골프장 후보를 찾는 중… (최대 45초)');cooldownUntil=Date.now()+15000;
try{const response=await fetch('https://overpass-api.de/api/interpreter',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded;charset=UTF-8'},body:new URLSearchParams({data:query}),signal:aborter.signal});if(!response.ok)throw new Error(`검색 서버 응답 ${response.status}. 잠시 후 다시 시도해 주세요.`);const data=await response.json();if(id!==sequence)return;if(data.remark)throw new Error('검색 서버가 불완전한 결과를 반환했습니다. 범위를 줄여 다시 분석해 주세요.');if(!Array.isArray(data.elements))throw new Error('검색 응답 형식이 올바르지 않습니다.');snapshot={bounds:{...b},time:new Date().toLocaleString('ko-KR',{timeZone:'Asia/Seoul'})+' KST',dataTime:data.osm3s?.timestamp_osm_base,rawCount:data.elements.length,items:normalize(data.elements,b)};render();status(`${snapshot.items.length}개 지도 후보 발견 · 최대 ${limit()}곳 표시 · 순위 미산정 · ${snapshot.time}`);
}catch(error){if(id!==sequence)return;status(timedOut?'검색 시간이 초과되었습니다. 범위를 줄여 다시 시도하세요. 이전 결과를 유지합니다.':error.name==='AbortError'?'분석이 취소되었습니다.':`${error.message} 이전 결과를 유지합니다.`,true);}finally{clearTimeout(timer);if(id===sequence){controller=null;lockMap(false);$('analyzeButton').disabled=false;$('cancelButton').hidden=true;}}}
function shareURL(){if(!map)return location.href;const u=new URL(location.href),c=map.getCenter();u.search='';u.searchParams.set('lat',c.lat.toFixed(5));u.searchParams.set('lon',c.lng.toFixed(5));u.searchParams.set('z',map.getZoom());u.searchParams.set('sort',$('sortSelect').value);u.searchParams.set('limit',limit());u.searchParams.set('provider',$('providerSelect').value);if($('playDate').value)u.searchParams.set('date',$('playDate').value);u.searchParams.set('party',$('partySize').value);if($('searchInput').value)u.searchParams.set('q',$('searchInput').value.slice(0,100));return u.href;}
$('analyzeButton').addEventListener('click',analyze);$('cancelButton').addEventListener('click',()=>{cancel();lockMap(false);});$('koreaButton').addEventListener('click',()=>map?.fitBounds([[33,124.5],[38.7,131]]));
for(const id of ['searchInput','sortSelect','limitSelect'])$(id).addEventListener(id==='searchInput'?'input':'change',()=>{render();if(snapshot)status(`${snapshot.items.length}개 스냅샷 후보 중 ${selected().length}곳 표시 · 순위 미산정`);});
$('shareButton').addEventListener('click',async()=>{try{await navigator.clipboard.writeText(shareURL());status('지도 화면 링크를 복사했습니다. 수신자는 다시 분석해야 합니다.');}catch{const u=shareURL();status('자동 복사를 사용할 수 없습니다. 아래 링크를 선택해 복사하세요.');const input=document.createElement('input');input.value=u;input.readOnly=true;$('status').append(input);input.select();}});
$('downloadButton').addEventListener('click',()=>{if(!snapshot)return;const html=reportHTML(snapshot,selected(),`${$('sortSelect').selectedOptions[0].textContent} / 최대 ${limit()}`,{date:$('playDate').value,partySize:Number($('partySize').value),compareCourses:[...compareIds].map(findCourse).filter(Boolean)});const url=URL.createObjectURL(new Blob([html],{type:'text/html;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=`FRI-ATLAS-${new Date().toISOString().slice(0,10)}.html`;a.click();setTimeout(()=>URL.revokeObjectURL(url),3000);status('HTML 자료를 저장했습니다. 메일 앱에서 파일을 직접 첨부할 수 있습니다.');});
$('mailButton').addEventListener('click',()=>{const body=`FRI ATLAS 골프장 비교 자료를 공유합니다.\n분석시각: ${snapshot.time}\n후보: ${selected().length}곳 / 순위 미산정\n지도 화면: ${shareURL()}\n\nHTML 저장 버튼으로 받은 파일을 직접 첨부해 주세요. 가격·예약은 미확인입니다.`;location.href=`mailto:?subject=${encodeURIComponent('FRI ATLAS · 다음 라운드 후보')}&body=${encodeURIComponent(body)}`;});
$('aboutButton').addEventListener('click',()=>$('aboutDialog').showModal());$('closeAbout').addEventListener('click',()=>$('aboutDialog').close());
if(['name','distance','evidence'].includes(params.get('sort')))$('sortSelect').value=params.get('sort');if(params.get('limit')==='20')$('limitSelect').value='20';$('searchInput').value=(params.get('q')||'').slice(0,100);if(params.get('provider')==='overpass')$('providerSelect').value='overpass';if(/^\d{4}-\d{2}-\d{2}$/.test(params.get('date')||''))$('playDate').value=params.get('date');if(['1','2','3','4'].includes(params.get('party')))$('partySize').value=params.get('party');
async function init(){if(!window.L){status('지도 라이브러리를 불러오지 못했습니다. 인터넷 연결 또는 CDN 접근을 확인해 주세요.',true);$('analyzeButton').disabled=true;return;}map=L.map('map',{worldCopyJump:false,minZoom:3,maxZoom:18,maxBounds:[[-85,-180],[85,180]]}).setView([number('lat',36.35,-80,80),number('lon',127.7,-180,180)],number('z',7,3,18));L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors',maxZoom:19}).on('tileerror',()=>status('일부 지도 타일을 불러오지 못했습니다. 네트워크를 확인하세요.',true)).addTo(map);if(!params.has('lat')&&!params.has('lon')&&!params.has('z'))map.fitBounds([[33,124.5],[38.7,131]]);layer=L.layerGroup().addTo(map);map.on('movestart',()=>{clearTimeout(movingTimer);$('motionState').textContent='EXPLORER';$('motionState').classList.add('explorer');});map.on('move',updateNavigator);map.on('moveend',()=>{updateNavigator();movingTimer=setTimeout(()=>{$('motionState').textContent='CATCH';$('motionState').classList.remove('explorer');},450);});updateNavigator();try{const response=await fetch('./catalog.json');if(!response.ok)throw new Error();catalogData=await response.json();catalog=normalizeCatalog(catalogData);renderCatalog();renderSaved();if($('providerSelect').value==='catalog')analyze();}catch{$('catalogResults').textContent='초기 카탈로그를 불러오지 못했습니다. 인터넷 연결을 확인하세요.';}}
renderSaved();if(document.readyState==='complete')init();else window.addEventListener('load',init,{once:true});




